package com.example.busbooking.domain.repository

import com.example.busbooking.data.dao.UserDAO
import com.example.busbooking.data.entity.User
import com.example.busbooking.domain.models.Result
import com.example.busbooking.utils.PasswordHasher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * AuthRepository - User authentication and account management
 *
 * Handles:
 * - Registration (email uniqueness check)
 * - Login (credential verification)
 * - Profile management
 *
 * Uses Dispatchers.IO for database operations (off main thread)
 */
interface IAuthRepository {
    suspend fun registerUser(name: String, email: String, password: String, phone: String): Result<Long>
    suspend fun loginUser(email: String, password: String): Result<User>
    suspend fun getUserProfile(userId: Long): Result<User>
    suspend fun updateUserProfile(user: User): Result<Unit>
    suspend fun logout(): Result<Unit>
}

/**
 * Implementation of AuthRepository
 *
 * @param userDAO Data access object for user queries
 */
class AuthRepository(private val userDAO: UserDAO) : IAuthRepository {

    /**
     * Register new user
     *
     * Process:
     * 1. Check if email already exists
     * 2. If exists, return Error("Email already registered")
     * 3. If not, create user with hashed password (in real app)
     * 4. Return rowId on success
     *
     * @return Result with userId if success, Error if failure
     */
    override suspend fun registerUser(
        name: String,
        email: String,
        password: String,
        phone: String
    ): Result<Long> = withContext(Dispatchers.IO) {
        try {
            // Check if email exists
            val exists = userDAO.emailExists(email)
            if (exists) {
                return@withContext Result.Error(
                    Exception("Email already registered"),
                    "This email is already associated with an account"
                )
            }

            // In production: hash password using BCrypt or Argon2
            val hashedPassword = PasswordHasher.hash(password)

            val user = User(
                name = name,
                email = email,
                password = hashedPassword,
                phone = phone,
                role = "USER", // Default role
                isBlocked = false,
                createdAt = System.currentTimeMillis()
            )

            val userId = userDAO.registerUser(user)
            return@withContext if (userId > 0) {
                Result.Success(userId)
            } else {
                Result.Error(
                    Exception("Registration failed"),
                    "Could not create account"
                )
            }
        } catch (e: Exception) {
            Result.Error(e, "Registration error: ${e.message}")
        }
    }

    /**
     * Login user
     *
     * Process:
     * 1. Query user by email
     * 2. Verify password (in real app: compare hashed)
     * 3. Return user object if credentials match
     * 4. Return error if not found or password mismatch
     *
     * @return Result with User if success, Error if failure
     */
    override suspend fun loginUser(email: String, password: String): Result<User> = withContext(Dispatchers.IO) {
        try {
            // Query user by email
            val user = userDAO.getUserByEmail(email)

            return@withContext if (user != null) {
                if (user.isBlocked) {
                    Result.Error(
                        Exception("Account blocked"),
                        "Your account has been blocked by admin"
                    )
                } else {
                    val storedPassword = user.password
                    val isVerified = if (PasswordHasher.isBcryptHash(storedPassword)) {
                        PasswordHasher.verify(password, storedPassword)
                    } else {
                        storedPassword == password
                    }

                    if (isVerified) {
                        if (!PasswordHasher.isBcryptHash(storedPassword)) {
                            val upgradedHash = PasswordHasher.hash(password)
                            userDAO.updatePassword(user.id, upgradedHash)
                        }
                        Result.Success(user)
                    } else {
                        Result.Error(
                            Exception("Invalid credentials"),
                            "Email or password is incorrect"
                        )
                    }
                }
            } else {
                Result.Error(
                    Exception("Invalid credentials"),
                    "Email or password is incorrect"
                )
            }
        } catch (e: Exception) {
            Result.Error(e, "Login error: ${'$'}{e.message}")
        }
    }

    /**
     * Get user profile by ID
     *
     * @return Result with User if found, Error if not found
     */
    override suspend fun getUserProfile(userId: Long): Result<User> = withContext(Dispatchers.IO) {
        try {
            val user = userDAO.getUserByIdSuspend(userId)
            return@withContext if (user != null) {
                Result.Success(user)
            } else {
                Result.Error(
                    Exception("User not found"),
                    "User profile not found"
                )
            }
        } catch (e: Exception) {
            Result.Error(e, "Error fetching profile: ${e.message}")
        }
    }

    /**
     * Update user profile
     *
     * @return Result.Success if update succeeds, Error otherwise
     */
    override suspend fun updateUserProfile(user: User): Result<Unit> = withContext(Dispatchers.IO) {
        try {
            userDAO.updateUser(user)
            return@withContext Result.Success(Unit)
        } catch (e: Exception) {
            Result.Error(e, "Error updating profile: ${e.message}")
        }
    }

    /**
     * Logout (clear session in SessionManager)
     * Note: SessionManager clearing should be done in a service or ViewModel
     */
    override suspend fun logout(): Result<Unit> = withContext(Dispatchers.IO) {
        try {
            // Session is managed in SessionManager, nothing to do in DAO
            Result.Success(Unit)
        } catch (e: Exception) {
            Result.Error(e, "Logout error: ${e.message}")
        }
    }
}

package com.example.busbooking.domain.repository

import com.example.busbooking.data.dao.UserDAO
import com.example.busbooking.data.entity.User
import com.example.busbooking.domain.models.Result
import com.example.busbooking.utils.PasswordHasher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * AuthRepository - User authentication and account management
 *
 * Handles:
 * - Registration (email uniqueness check)
 * - Login (credential verification)
 * - Profile management
 *
 * Uses Dispatchers.IO for database operations (off main thread)
 */
interface IAuthRepository {
    suspend fun registerUser(name: String, email: String, password: String, phone: String): Result<Long>
    suspend fun loginUser(email: String, password: String): Result<User>
    suspend fun getUserProfile(userId: Long): Result<User>
    suspend fun updateUserProfile(user: User): Result<Unit>
    suspend fun logout(): Result<Unit>
}

/**
 * Implementation of AuthRepository
 *
 * @param userDAO Data access object for user queries
 */
class AuthRepository(private val userDAO: UserDAO) : IAuthRepository {

    /**
     * Register new user
     *
     * Process:
     * 1. Check if email already exists
     * 2. If exists, return Error("Email already registered")
     * 3. If not, create user with hashed password (in real app)
     * 4. Return rowId on success
     *
     * @return Result with userId if success, Error if failure
     */
    override suspend fun registerUser(
        name: String,
        email: String,
        password: String,
        phone: String
    ): Result<Long> = withContext(Dispatchers.IO) {
        try {
            // Check if email exists
            val exists = userDAO.emailExists(email)
            if (exists) {
                return@withContext Result.Error(
                    Exception("Email already registered"),
                    "This email is already associated with an account"
                )
            }

            // In production: hash password using BCrypt or Argon2
            val hashedPassword = PasswordHasher.hash(password)

            val user = User(
                name = name,
                email = email,
                password = hashedPassword,
                phone = phone,
                role = "USER", // Default role
                isBlocked = false,
                createdAt = System.currentTimeMillis()
            )

            val userId = userDAO.registerUser(user)
            return@withContext if (userId > 0) {
                Result.Success(userId)
            } else {
                Result.Error(
                    Exception("Registration failed"),
                    "Could not create account"
                )
            }
        } catch (e: Exception) {
            Result.Error(e, "Registration error: ${e.message}")
        }
    }

     /**
      * Login user
      *
      * Process:
      * 1. Query user by phone
      * 2. Verify password (in real app: compare hashed)
      * 3. Return user object if credentials match
      * 4. Return error if not found or password mismatch
      *
      * @return Result with User if success, Error if failure
      */
     override suspend fun loginUser(email: String, password: String): Result<User> = withContext(Dispatchers.IO) {
         try {
             // Query user by phone
             val user = userDAO.getUserByPhone(email)

            return@withContext if (user != null) {
                if (user.isBlocked) {
                    Result.Error(
                        Exception("Account blocked"),
                        "Your account has been blocked by admin"
                    )
                } else {
                    val storedPassword = user.password
                    val isVerified = if (PasswordHasher.isBcryptHash(storedPassword)) {
                        PasswordHasher.verify(password, storedPassword)
                    } else {
                        storedPassword == password
                    }

                    if (isVerified) {
                        if (!PasswordHasher.isBcryptHash(storedPassword)) {
                            val upgradedHash = PasswordHasher.hash(password)
                            userDAO.updatePassword(user.id, upgradedHash)
                        }
                        Result.Success(user)
                    } else {
                        Result.Error(
                            Exception("Invalid credentials"),
                            "Email or password is incorrect"
                        )
                    }
                }
            } else {
                Result.Error(
                    Exception("Invalid credentials"),
                    "Email or password is incorrect"
                )
            }
        } catch (e: Exception) {
            Result.Error(e, "Login error: ${'$'}{e.message}")
        }
    }

    /**
     * Get user profile by ID
     *
     * @return Result with User if found, Error if not found
     */
    override suspend fun getUserProfile(userId: Long): Result<User> = withContext(Dispatchers.IO) {
        try {
            val user = userDAO.getUserByIdSuspend(userId)
            return@withContext if (user != null) {
                Result.Success(user)
            } else {
                Result.Error(
                    Exception("User not found"),
                    "User profile not found"
                )
            }
        } catch (e: Exception) {
            Result.Error(e, "Error fetching profile: ${e.message}")
        }
    }

    /**
     * Update user profile
     *
     * @return Result.Success if update succeeds, Error otherwise
     */
    override suspend fun updateUserProfile(user: User): Result<Unit> = withContext(Dispatchers.IO) {
        try {
            userDAO.updateUser(user)
            return@withContext Result.Success(Unit)
        } catch (e: Exception) {
            Result.Error(e, "Error updating profile: ${e.message}")
        }
    }

    /**
     * Logout (clear session in SessionManager)
     * Note: SessionManager clearing should be done in a service or ViewModel
     */
    override suspend fun logout(): Result<Unit> = withContext(Dispatchers.IO) {
        try {
            // Session is managed in SessionManager, nothing to do in DAO
            Result.Success(Unit)
        } catch (e: Exception) {
            Result.Error(e, "Logout error: ${e.message}")
        }
    }
}

package com.example.busbooking.presentation.ui

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Button
import android.widget.EditText
import android.widget.ProgressBar
import android.widget.TextView
import androidx.fragment.app.Fragment
import androidx.fragment.app.viewModels
import androidx.navigation.fragment.findNavController
import androidx.navigation.fragment.navArgs
import androidx.recyclerview.widget.GridLayoutManager
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.example.busbooking.R
import com.example.busbooking.presentation.viewmodel.BusViewModel
import com.google.android.material.floatingactionbutton.FloatingActionButton

// ─────────────────────────────────────────────────────────────────────────────
// 1. BusListAdminFragment
// ─────────────────────────────────────────────────────────────────────────────

class BusListAdminFragment : Fragment() {

    private val viewModel: BusViewModel by viewModels()

    private lateinit var recyclerView: RecyclerView
    private lateinit var progressBar: ProgressBar
    private lateinit var emptyText: TextView
    private lateinit var errorText: TextView
    private lateinit var addBusFab: FloatingActionButton

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View? = inflater.inflate(R.layout.fragment_bus_list_admin, container, false)

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        recyclerView = view.findViewById(R.id.busRecyclerView)
        progressBar  = view.findViewById(R.id.progressBar)
        emptyText    = view.findViewById(R.id.emptyText)
        errorText    = view.findViewById(R.id.errorText)
        addBusFab    = view.findViewById(R.id.addBusFab)

        recyclerView.layoutManager = LinearLayoutManager(requireContext())

        addBusFab.setOnClickListener {
            findNavController().navigate(R.id.action_busListAdminFragment_to_busFormAdminFragment)
        }

        viewModel.busState.observe(viewLifecycleOwner) { state ->
            when (state) {
                is androidx.lifecycle.LiveData -> {} // Placeholder
                else -> {
                    progressBar.visibility = View.GONE
                    emptyText.text = "Chưa có xe nào"
                    emptyText.visibility = View.VISIBLE
                }
            }
        }

        viewModel.loadAllBuses()
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. BusFormAdminFragment — Tạo mới hoặc chỉnh sửa xe (busId == -1L = tạo mới)
// ─────────────────────────────────────────────────────────────────────────────

class BusFormAdminFragment : Fragment() {

    private val args: BusFormAdminFragmentArgs by navArgs()

    private lateinit var busNameInput: EditText
    private lateinit var licensePlateInput: EditText
    private lateinit var totalSeatsInput: EditText
    private lateinit var saveButton: Button
    private lateinit var progressBar: ProgressBar
    private lateinit var errorText: TextView

    private val isEditMode get() = args.busId != -1L

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View? = inflater.inflate(R.layout.fragment_bus_form_admin, container, false)

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        busNameInput      = view.findViewById(R.id.busNameInput)
        licensePlateInput = view.findViewById(R.id.licensePlateInput)
        totalSeatsInput   = view.findViewById(R.id.totalSeatsInput)
        saveButton        = view.findViewById(R.id.saveButton)
        progressBar       = view.findViewById(R.id.progressBar)
        errorText         = view.findViewById(R.id.errorText)

        saveButton.text = if (isEditMode) "Cập nhật" else "Tạo xe"

        saveButton.setOnClickListener {
            val busName      = busNameInput.text.toString().trim()
            val licensePlate = licensePlateInput.text.toString().trim()
            val totalSeats   = totalSeatsInput.text.toString().trim().toIntOrNull() ?: 0

            if (busName.isBlank() || licensePlate.isBlank() || totalSeats <= 0) {
                showError("Vui lòng điền đầy đủ thông tin hợp lệ")
                return@setOnClickListener
            }

            // TODO: inject BusViewModel và gọi createBus / updateBus
            // viewModel.createBus(busName, totalSeats, licensePlate)
            findNavController().popBackStack()
        }
    }

    private fun showError(message: String) {
        errorText.text       = message
        errorText.visibility = View.VISIBLE
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. SeatManagementFragment — Quản lý ghế của một xe (theo args.busId)
// ─────────────────────────────────────────────────────────────────────────────

class SeatManagementFragment : Fragment() {

    private val args: SeatManagementFragmentArgs by navArgs()

    private lateinit var recyclerView: RecyclerView
    private lateinit var progressBar: ProgressBar
    private lateinit var emptyText: TextView
    private lateinit var errorText: TextView
    private lateinit var generateSeatsButton: Button

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View? = inflater.inflate(R.layout.fragment_seat_management, container, false)

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        recyclerView        = view.findViewById(R.id.seatsRecyclerView)
        progressBar         = view.findViewById(R.id.progressBar)
        emptyText           = view.findViewById(R.id.emptyText)
        errorText           = view.findViewById(R.id.errorText)
        generateSeatsButton = view.findViewById(R.id.generateSeatsButton)

        // Hiển thị ghế dạng lưới 4 cột (bố cục xe khách thông thường)
        recyclerView.layoutManager = GridLayoutManager(requireContext(), 4)

        generateSeatsButton.setOnClickListener {
            // TODO: inject SeatViewModel và tạo ghế tự động cho busId
            // viewModel.generateSeats(args.busId, totalSeats)
        }

        // TODO: load danh sách ghế theo args.busId
        emptyText.text       = "Chưa có ghế nào. Nhấn 'Tạo ghế' để tạo tự động."
        emptyText.visibility = View.VISIBLE
    }
}

package com.example.busbooking.presentation.ui

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Button
import android.widget.EditText
import android.widget.ProgressBar
import android.widget.TextView
import androidx.fragment.app.Fragment
import androidx.fragment.app.viewModels
import androidx.navigation.fragment.findNavController
import androidx.navigation.fragment.navArgs
import androidx.recyclerview.widget.GridLayoutManager
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.example.busbooking.presentation.viewmodel.BusState

// ─────────────────────────────────────────────────────────────────────────────
// 1. BusListAdminFragment
// ─────────────────────────────────────────────────────────────────────────────

class BusListAdminFragment : Fragment() {

    private val viewModel: BusViewModel by viewModels()

    private lateinit var recyclerView: RecyclerView
    private lateinit var progressBar: ProgressBar
    private lateinit var emptyText: TextView
    private lateinit var errorText: TextView
    private lateinit var addBusFab: FloatingActionButton

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View? = inflater.inflate(R.layout.fragment_bus_list_admin, container, false)

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        recyclerView = view.findViewById(R.id.busRecyclerView)
        progressBar  = view.findViewById(R.id.progressBar)
        emptyText    = view.findViewById(R.id.emptyText)
        errorText    = view.findViewById(R.id.errorText)
        addBusFab    = view.findViewById(R.id.addBusFab)

        recyclerView.layoutManager = LinearLayoutManager(requireContext())

        addBusFab.setOnClickListener {
            findNavController().navigate(R.id.action_busListAdminFragment_to_busFormAdminFragment)
        }

        viewModel.busState.observe(viewLifecycleOwner) { state ->
            when (state) {
                is BusState.Loading -> {
                    progressBar.visibility = View.VISIBLE
                    recyclerView.visibility = View.GONE
                    emptyText.visibility = View.GONE
                    errorText.visibility = View.GONE
                }
                is BusState.BusesLoaded -> {
                    progressBar.visibility = View.GONE
                    errorText.visibility = View.GONE
                    if (state.buses.isEmpty()) {
                        emptyText.text = "Chưa có xe nào"
                        emptyText.visibility = View.VISIBLE
                        recyclerView.visibility = View.GONE
                    } else {
                        emptyText.visibility = View.GONE
                        recyclerView.visibility = View.VISIBLE
                        // TODO: Set adapter với state.buses
                    }
                }
                is BusState.Error -> {
                    progressBar.visibility = View.GONE
                    recyclerView.visibility = View.GONE
                    emptyText.visibility = View.GONE
                    errorText.text = state.message
                    errorText.visibility = View.VISIBLE
                }
                else -> {
                    progressBar.visibility = View.GONE
                }
            }
        }

        viewModel.loadAllBuses()
    }
}

