/** Trả về timestamp (ms) = ngày D kể từ hôm nay + giờ HH:mm */ private fun ts(dayOffset: Int, hour: Int, minute: Int): Long { return todayMidnight() + dayOffset * 86_400_000L + hour * 3_600_000L + minute * 60_000L }
