// ------------------------------------------------------- // Khung giờ xuất phát điển hình cho mỗi loại tuyến // ------------------------------------------------------- /** Khung giờ (hour, minute) cho tuyến ngắn < 3h */ private val SHORT_SLOTS = listOf( 6 to 0, 7 to 0, 8 to 30, 10 to 0, 11 to 30, 13 to 0, 14 to 30, 16 to 0, 17 to 30, 19 to 0 ) /** Khung giờ cho tuyến vừa 3–7h */ private val MID_SLOTS = listOf( 5 to 0, 6 to 30, 8 to 0, 10 to 0, 12 to 0, 14 to 0, 16 to 0, 18 to 0, 20 to 0, 22 to 0 ) /** Khung giờ cho tuyến dài > 7h (nhiều chuyến đêm) */ private val LONG_SLOTS = listOf( 7 to 0, 9 to 0, 12 to 0, 15 to 0, 18 to 0, 20 to 0, 22 to 0, 23 to 30 )
private fun slotsFor(durationMs: Long) = when { durationMs < 3 * 3600_000 -> SHORT_SLOTS durationMs < 7 * 3600_000 -> MID_SLOTS else -> LONG_SLOTS }
// ------------------------------------------------------- // Tên bus (chỉ dùng Tân Quang Dũng) + biển số giả // ------------------------------------------------------- private val BUS_PLATES = listOf( "43A-12345", "43A-23456", "43A-34567", "43A-45678", "43A-56789", "43B-11111", "43B-22222", "43B-33333", "43B-44444", "43B-55555", "43C-10001", "43C-20002", "43C-30003", "43C-40004", "43C-50005" )
// ------------------------------------------------------- // Seed entry point // ------------------------------------------------------- fun seedDatabase(db: SupportSQLiteDatabase) { try { seedUsers(db) val routeIds = seedRoutes(db) val busIds = seedBuses(db) seedSeats(db, busIds) seedTrips(db, routeIds, busIds) seedTickets(db) println("✅ Database seeded successfully!") } catch (e: Exception) { e.printStackTrace() } }
// ------------------------------------------------------- // Users // ------------------------------------------------------- private fun seedUsers(db: SupportSQLiteDatabase) { val adminPw = PasswordHasher.hash("123") val userPw = PasswordHasher.hash("123") db.execSQL("INSERT OR REPLACE INTO users (id,name,email,password,phone,role) VALUES (?,?,?,?,?,?)", arrayOf<Any?>(1,"Admin","admin@bus.com",adminPw,"0123456789","ADMIN")) db.execSQL("INSERT OR REPLACE INTO users (id,name,email,password,phone,role) VALUES (?,?,?,?,?,?)", arrayOf<Any?>(2,"Nguyễn Văn A","user@gmail.com",userPw,"0987654321","USER")) db.execSQL("INSERT OR REPLACE INTO users (id,name,email,password,phone,role) VALUES (?,?,?,?,?,?)", arrayOf<Any?>(3,"Trần Thị B","userb@gmail.com",userPw,"0912345678","USER")) }
// ------------------------------------------------------- // Routes → trả về Map<index, routeId> // ------------------------------------------------------- fun seedRoutes(db: SupportSQLiteDatabase): Map<Int, Int> { val now = System.currentTimeMillis() val idMap = mutableMapOf<Int, Int>() ROUTES.forEachIndexed { idx, r -> val id = idx + 1 idMap[idx] = id db.execSQL( "INSERT OR REPLACE INTO routes (id,origin,destination,distance,isActive,createdAt) VALUES (?,?,?,?,?,?)", arrayOf<Any?>(id, r.originName, r.destName, r.distanceKm, 1, now) ) } return idMap }
// ------------------------------------------------------- // Buses → trả về List<busId> // ------------------------------------------------------- fun seedBuses(db: SupportSQLiteDatabase): List<Int> { val now = System.currentTimeMillis() val ids = mutableListOf<Int>() BUS_PLATES.forEachIndexed { idx, plate -> val id = idx + 1 ids += id db.execSQL( "INSERT OR REPLACE INTO buses (id,busName,totalSeats,licensePlate,seatLayoutJson,isActive,createdAt) VALUES (?,?,?,?,?,?,?)", arrayOf<Any?>(id, "Xe Tân Quang Dũng", 40, plate, "", 1, now) ) } return ids }
// ------------------------------------------------------- // Seats // ------------------------------------------------------- private fun seedSeats(db: SupportSQLiteDatabase, busIds: List<Int>) { var seatId = 1
busIds.forEach { busId ->
// ========================= // TẦNG 1 - A (17 ghế) // =========================
for (seatNumber in 1..17) { db.execSQL( "INSERT OR REPLACE INTO seats (id, busId, seatNumber) VALUES (?, ?, ?)", arrayOf<Any?>( seatId, busId, "A$seatNumber" ) ) seatId++ }
// ========================= // TẦNG 2 - B (17 ghế) // =========================
for (seatNumber in 1..17) { db.execSQL( "INSERT OR REPLACE INTO seats (id, busId, seatNumber) VALUES (?, ?, ?)", arrayOf<Any?>( seatId, busId, "B$seatNumber" ) ) seatId++ } } }
// ------------------------------------------------------- // Trips — 3 ngày tiếp theo, mỗi tuyến nhiều khung giờ // ------------------------------------------------------- fun seedTrips(db: SupportSQLiteDatabase, routeIds: Map<Int, Int>, busIds: List<Int>) { val now = System.currentTimeMillis() var tripId = 1 var busIdx = 0 // round-robin qua fleet
for (dayOffset in 1..3) { ROUTES.forEachIndexed { routeIdx, route -> val routeId = routeIds[routeIdx] ?: return@forEachIndexed val slots = slotsFor(route.durationMs) val tripPrice = price(route.originKey, route.destKey)
slots.forEach { (hour, minute) -> val depart = ts(dayOffset, hour, minute) val arrive = depart + route.durationMs val dayMidnight = dayTs(dayOffset) val busId = busIds[busIdx % busIds.size] busIdx++
db.execSQL( """INSERT OR REPLACE INTO trips (id,routeId,busId,departureTime,arrivalTime,price,tripDate,status,createdAt) VALUES (?,?,?,?,?,?,?,?,?)""", arrayOf<Any?>( tripId, routeId, busId, depart, arrive, tripPrice, dayMidnight, "SCHEDULED", now ) ) tripId++ } } } println("✅ Seeded ${tripId - 1} trips across 3 days for ${ROUTES.size} routes.") }
// ------------------------------------------------------- // Sample tickets // ------------------------------------------------------- private fun seedTickets(db: SupportSQLiteDatabase) { val now = System.currentTimeMillis() // Ghế 1 & 2 trên chuyến đầu tiên của ngày đầu tiên (tripId = 1) db.execSQL("INSERT OR REPLACE INTO tickets (id,userId,tripId,seatId,bookingTime,status) VALUES (?,?,?,?,?,?)", arrayOf<Any?>(1, 2, 1, 1, now, "CONFIRMED")) db.execSQL("INSERT OR REPLACE INTO tickets (id,userId,tripId,seatId,bookingTime,status) VALUES (?,?,?,?,?,?)", arrayOf<Any?>(2, 2, 1, 2, now, "CONFIRMED")) db.execSQL("INSERT OR REPLACE INTO tickets (id,userId,tripId,seatId,bookingTime,status) VALUES (?,?,?,?,?,?)", arrayOf<Any?>(3, 3, 2, 41, now, "CONFIRMED")) } }

